frappe.ui.form.on("Transfer Outs", {
    get_from_material_request: function(frm) {
        if (!frm.doc.get_from_material_request) {
            return;
        }

        frappe.call({
            method: "frappe.client.get",
            args: {
                doctype: "Material Request",
                name: frm.doc.get_from_material_request
            },
            callback: function(r) {
                if (!r.message) return;

                // Clear existing items
                frm.clear_table("items");

                (r.message.items || []).forEach(function(d) {
                    let row = frm.add_child("items");

                    row.item_code = d.item_code;
                    row.item_name = d.item_name;
                    row.description = d.description;
                    row.qty = d.qty;
                    row.uom = d.uom;
                    row.stock_uom = d.stock_uom;
                    row.conversion_factor = d.conversion_factor;
                    row.warehouse = frm.doc.set_warehouse;
                    row.material_request = r.message.name;
                    row.material_request_item = d.name;
                     frm.script_manager.trigger("item_code", row.doctype, row.name);
                     frm.script_manager.trigger("qty", row.doctype, row.name);
                });

                frm.refresh_field("items");
            }
        });
    }
});
frappe.ui.form.on("Transfer Outs", {
	setup: function(frm) {
		frm.set_query("get_from_material_request", function() {
			return {
				filters: {
					set_warehouse :["=",frm.doc.target_warehouse]
				}
			};
		});
	}
});
frappe.ui.form.on('Transfer Outs Item', {
    qty: function(frm, cdt, cdn) {
   
            var item = locals[cdt][cdn];
            item.sales_price = item.rate * item.qty;
            frm.refresh_field('items');
            updateTotalQty(frm);
         
    },
    items_remove: function(frm, cdt, cdn) {
        updateTotalQty(frm);
        frm.trigger('qty');
    }
});

function updateTotalQty(frm) {
    var total_qty = 0;
    var total = 0;

    $.each(frm.doc.items || [], function (i, item) {
        total_qty += item.qty || 0;
        total += (item.qty || 0) * (item.rate || 0);
    });

    frm.set_value('total_qty', total_qty);
    frm.set_value('total', total);
    frm.refresh_field('total_qty');
    frm.refresh_field('total');
}

frappe.ui.form.on('Transfer Outs', {
    validate: function(frm) {

        for (let item of frm.doc.items) {

            if (item.available_qty < item.qty) {
                frappe.throw(
                    __("Item {0} — Qty must be less than available qty", [item.item_code])
                );
            }

            // if (!item.sales_price || item.sales_price <= 0) {
            //     frappe.throw(
            //         __("Item {0} — Sales Price must be greater than 0", [item.item_code])
            //     );
            // }

        }
    }
});

frappe.ui.form.on('Transfer Out Items', {
    item_code: function(frm, cdt, cdn) {
        
        var row = locals[cdt][cdn];
       
        
        if (row.item_code) {
                frappe.call({
                    method: 'frappe.client.get',
                    args: {
                        doctype: 'Item',
                        name: row.item_code
                    },
                    callback: function(r) {
                        if (r.message) {
                            // Replace 'description' with your actual field name in the child table
                            frappe.model.set_value(cdt, cdn, 'item_name', r.message.item_name);
                            frappe.model.set_value(cdt, cdn, 'uom', r.message.stock_uom);
                        }
                    }
                });
            }
        
            if(frm.doc.set_warehouse && row.item_code){
                frappe.call({
                    method: "frappe.client.get_value",
                    args: {
                        doctype: "Bin",
                        filters: { "item_code":row.item_code,"warehouse":frm.doc.set_warehouse},
                        "fieldname": "actual_qty"
                    },
                      method: "spokes_unitec_app.script.stock_details_pos",
                    args: {
                        product_code: row.item_code,
                        warehouse: frm.doc.set_warehouse,
                    },
                    callback: function(r) {
                        
                        if(r.message[0].actual_qty){
                            frappe.model.set_value(row.doctype, row.name, 'available_qty', r.message[0].actual_qty);
                        }else{
                            frappe.model.set_value(row.doctype, row.name, 'available_qty', 0);
                        }
                    }
                })
                frappe.call({
                    method: "frappe.client.get_value",
                    args: {
                        doctype: "Item Price",
                        filters: {
                            "item_code": row.item_code, 
                            "price_list": "Standard Buying"
                        },
                        "fieldname": "price_list_rate"
                    },
                    callback: function(r) {
                        if(r.message.price_list_rate){
                            frappe.model.set_value(row.doctype, row.name, 'rate', r.message.price_list_rate);
                            
                                                        frappe.model.set_value(row.doctype, row.name, 'sales_price', r.message.price_list_rate);

                        }else{
                            frappe.model.set_value(row.doctype, row.name, 'rate', 0);
                        }
                    }
                })
            }
          
    }
});

