frappe.ui.form.on("Sales Invoice", {
    refresh(frm) {

            
                frm.add_custom_button("Print All", function () {
                    frm.events.printall();
                });
            
        
    },
    
    printall: function (btn, callback, on_error) {
    	    const print_settings = frappe.model.get_doc(':Print Settings', 'Print Settings');
    		const allow_print_for_draft = cint(print_settings.allow_print_for_draft);
    		const is_submittable = frappe.model.is_submittable(cur_frm.doctype);
    		const allow_print_for_cancelled = cint(print_settings.allow_print_for_cancelled);  
    		console.log('test');
    		let printformat_data = [];

    		const dialog = frappe.prompt({fieldname: 'printformats', fieldtype: 'Table', label: __('Print Formats'),
    			fields: [{
    					fieldtype:'Link',
    					fieldname:'printformat',
    					label: __('Print Format'),
    					read_only:1,
    					in_list_view:1
    				},
    				{
    					fieldtype:'Data',
    					fieldname:'name',
    					label: __('Operation Id')
    				}
    			],
    			data: printformat_data,
    			in_place_edit: true,
    			get_data: function() {
    				return printformat_data;
    			}
    		}, function(data){
                console.log(data);
                const json_string = JSON.stringify(data.printformats);
                const w = window.open('/api/method/spokes_unitec_app.print_format.download_multi_pdf?' +
					'doctype=' + encodeURIComponent(cur_frm.doctype) +
					'&name=' + encodeURIComponent(cur_frm.doc.name) +
					'&count=' + encodeURIComponent(cur_frm.doc.print_count) +
					'&format=' + encodeURIComponent(json_string) +
					'&no_letterhead=' + '1');
				
					
				if (!w) {
					frappe.msgprint(__('Please enable pop-ups'));
					return;
				}
    		}, __("Print"), __("Print"));
    		
    		dialog.fields_dict["printformats"].grid.wrapper.find('.grid-add-row').hide();
    dialog.fields_dict.printformats.df.data = [];
 
    const desiredOrder = ["Sales Invoice", "SI-Duplicate for Transporter", "SI-Triplicate for Supplier", "SI-Extra Copy"];

    const orderedPrintFormats = frappe.meta.get_print_formats(cur_frm.doctype)
       .filter(data => desiredOrder.includes(data))
       .sort((a, b) => desiredOrder.indexOf(a) - desiredOrder.indexOf(b));


  orderedPrintFormats.forEach(data => {
     dialog.fields_dict.printformats.df.data.push({
         'name': data,
         'printformat': data,
    });
});
    		dialog.fields_dict.printformats.grid.refresh();
    				// dialog.fields_dict.printformats.grid.cannot_delete_rows = true;
    	}
});

