                if (!r.message) return;

                // Clear existing items
                frm.clear_table("items");

                (r.message.items || []).forEach(function(d) {
                    let row = frm.add_child("items");

                    row.item_code = d.item_code;
                    row.item_name = d.item_name;
                    row.description = d.description;
                    row.qty = d.qty;
                    row.uom = d.uom;
                    row.stock_uom = d.stock_uom;
                    row.conversion_factor = d.conversion_factor;
                    row.warehouse = frm.doc.set_warehouse;
                    row.material_request = r.message.name;
                    row.material_request_item = d.name;
                     frm.script_manager.trigger("item_code", row.doctype, row.name);
                     frm.script_manager.trigger("qty", row.doctype, row.name);
                });

                frm.refresh_field("items");
            }
        });
         frappe.call({
                                method: "spokes_unitec_app.script.get_warehouse_address",
                                args: {
                                    branch_name: frm.doc.to_branch
                                },
                       callback: function (r) {
                                    frm.set_value("customer_address",r.message[0].parent );
                                    frm.set_value("shipping_address_name",r.message[0].parent );
                                    frm.set_value("billing_address_gstin",r.message[0].gstin );

                                }
        });       



        if(frm.doc.from_branch){
        frappe.call({
                                method: "spokes_unitec_app.script.get_warehouse_address",
                                args: {
                                    branch_name: frm.doc.from_branch
                                },
                       callback: function (r) {
                                    frm.set_value("company_address",r.message[0].parent );
                                     frm.set_value("company_gstin",r.message[0].gstin );

                                }
        });


    }
    }
});
