frappe.ui.form.on("TMS Regrind Cycle", {
    refresh(frm) {

        if (
            frm.doc.docstatus === 1 && !frm.doc.rgf_stock_entry
            
        ) {

            frm.add_custom_button("Complete Regrind", function () {

                if (!frm.doc.inspection_result) {
                    frappe.msgprint("Please select Inspection Result.");
                    return;
                }

                let dialog = new frappe.ui.Dialog({
                    title: "Complete Regrind",
                    fields: [
                        {
                            label: "Total Regrind Qty",
                            fieldname: "total_qty",
                            fieldtype: "Float",
                            default: frm.doc.qty,
                            read_only: 1
                        },
                        {
                            label: "Completed Qty",
                            fieldname: "completed_qty",
                            fieldtype: "Float",
                            reqd: 1,
                            description: "Enter the quantity to complete in this regrind cycle."
                        },
                        {
                            label: "Inspection Result",
                            fieldname: "inspection_result",
                            fieldtype: "Select",
                            options: "Accepted\nRejected",
                            default: frm.doc.inspection_result,
                            reqd: 1
                        }
                    ],

                    primary_action_label: "Complete Regrind",

                    primary_action(values) {

                        let total_qty = flt(values.total_qty);
                        let completed_qty = flt(values.completed_qty);

                        if (completed_qty <= 0) {
                            frappe.msgprint("Completed Qty must be greater than 0.");
                            return;
                        }

                        if (completed_qty > total_qty) {
                            frappe.msgprint(
                                `Completed Qty cannot be greater than ${total_qty}.`
                            );
                            return;
                        }

                        dialog.hide();

                        frappe.call({
                            method: "tms.tms.doctype.tms_regrind_cycle.tms_regrind_cycle.complete_regrind",
                            args: {
                                docname: frm.doc.name,
                                inspection_result: values.inspection_result,
                                regrind_cost: frm.doc.regrind_cost,
                                completed_qty: completed_qty
                            },
                            freeze: true,
                            freeze_message: "Completing Regrind...",

                            callback: function(r) {
                                if (!r.exc) {
                                    frm.reload_doc();
                                }
                            }
                        });
                    }
                });

                dialog.show();

            });
        }
    }
});

