function create_regrind_rows(frm) {

	let qty = cint(frm.doc.qty || 0);

	if (!qty) {
		return;
	}


	let current_rows =
		frm.doc.regrind_count_detail || [];


	if (
		current_rows.length > 0
	) {

		return;

	}


	for (let i = 0; i < qty; i++) {

		let row = frm.add_child(
			"regrind_count_detail"
		);


		row.this_cycle_number = 1;

	}


	frm.refresh_field(
		"regrind_count_detail"
	);

}

