								row.item_code = item.item_code;
								row.item_name = item.item_name;
								row.qty = item.qty;
								row.condition = item.condition;
								row.serial_no = item.serial_no;

							});

							cur_frm.refresh_field("items");
						}
					);

				},
				__("Create")
			);
		}
	}
});

frappe.ui.form.on("TMS Used Tool Inspection Item", {

    add_serial_no: function(frm, cdt, cdn) {

        let row = locals[cdt][cdn];

        if (!row.item_code) {
            frappe.msgprint("Please select Item first.");
            return;
        }

        if (!row.qty || row.qty <= 0) {
            frappe.msgprint("Please enter Quantity first.");
            return;
        }

        if (!frm.doc.used_tool_warehouse) {
            frappe.msgprint("Please select Source Warehouse.");
            return;
        }

        frappe.call({
            method: "frappe.client.get_list",

            args: {
                doctype: "Serial No",

                filters: {
                    item_code: row.item_code,
                    warehouse: frm.doc.used_tool_warehouse,
                    status: "Active"
                },

                fields: [
                    "name",
                    "item_code",
                    "warehouse",
                    "status"
                ],

                limit_page_length: 1000
            },

            callback: function(r) {

                let serials = r.message || [];

                if (!serials.length) {

                    frappe.msgprint({
                        title: "No Serial Numbers",
                        indicator: "red",

                        message:
                            `No Active Serial Numbers found for Item <b>${row.item_code}</b>
                            in Warehouse <b>${frm.doc.used_tool_warehouse}</b>`
                    });

                    return;
                }


                let table_data = serials.map(d => {
                    return {
                        serial_no: d.name,
                        selected: 0
                    };
                });


                let dialog = new frappe.ui.Dialog({

                    title: "Select Serial Numbers",

                    fields: [

                        {
                            fieldname: "info",
                            fieldtype: "HTML",

                            options: `
                                <div style="margin-bottom:10px">
                                    <b>Item:</b> ${row.item_code}<br>
                                    <b>Warehouse:</b> ${frm.doc.used_tool_warehouse}<br>
                                    <b>Required Quantity:</b> ${row.qty}
                                </div>
                            `
                        },

                        {
                            fieldname: "serial_list",

                            fieldtype: "Table",

                            label: "Available Active Serial Numbers",

                            cannot_add_rows: true,

                            cannot_delete_rows: true,

                            in_place_edit: true,

                            data: table_data,

                            fields: [

                                {
                                    fieldname: "serial_no",

                                    label: "Serial No",

                                    fieldtype: "Data",

                                    in_list_view: 1,

                                    read_only: 1
                                },

                                {
                                    fieldname: "selected",

                                    label: "Select",

                                    fieldtype: "Check",

                                    in_list_view: 1
                                }

                            ]
                        }

                    ],

                    primary_action_label: "Add Selected Serials",

                    primary_action(values) {

                        let selected_serials =
                            (values.serial_list || [])
                            .filter(d => d.selected)
                            .map(d => d.serial_no);


                        let required_qty = flt(row.qty);


                        // No serial selected
                        if (!selected_serials.length) {

                            frappe.msgprint({
                                title: "Selection Required",
                                indicator: "red",

                                message: "Please select Serial Number."
                            });

                            return;
                        }


                        // Restrict based on Quantity
                        if (selected_serials.length !== required_qty) {

                            frappe.msgprint({

                                title: "Invalid Serial Number Count",

                                indicator: "red",

                                message:
                                    `Quantity is <b>${required_qty}</b>.<br><br>
                                    You must select exactly
                                    <b>${required_qty} Serial Number(s)</b>.<br><br>
                                    Currently selected:
                                    <b>${selected_serials.length}</b>`

                            });

                            return;
                        }


                        // Set Serial Numbers
                        frappe.model.set_value(

                            cdt,
                            cdn,

                            "serial_no",

                            selected_serials.join("\n")

                        );


                        dialog.hide();

                        frappe.show_alert({

                            message:
                                `${selected_serials.length} Serial Number(s) added.`,

                            indicator: "green"

                        });

                    }

                });


                dialog.show();

            }

        });

    }

});


